import importlib.util,json,uuid,hashlib
from pathlib import Path
s=importlib.util.spec_from_file_location('m',Path(__file__).with_name('live-common.py'));m=importlib.util.module_from_spec(s);s.loader.exec_module(m);file='large-repair.json'
def rec(id,steps,expected,r,ok):m.rec(id,steps,expected,m.payload(r) if hasattr(r,'status_code') else r,ok,'admin',file)
doc={'bomFormat':'CycloneDX','specVersion':'1.6','serialNumber':'urn:uuid:'+str(uuid.uuid4()),'version':1,'components':[{'type':'LIBRARY' if i==0 else 'library','bom-ref':'r3-large-'+str(i),'name':'r3-large-'+str(i),'version':'1.0','description':'Bounded local UAT text. '*1100} for i in range(220)]};raw=json.dumps(doc,indent=2).encode();digest=hashlib.sha256(raw).hexdigest();assert 5*1024*1024<len(raw)<8*1024*1024
r=m.call('/api/sboms/upload','POST',data={'sbom_name':'UAT R3 bounded large repair '+str(uuid.uuid4())},files={'file':('large.cdx.json',raw,'application/json')});assert r.status_code==422,m.payload(r);sid=r.json()['detail']['session_id'];base='/api/sbom-validation-sessions/'+sid
r=m.call(base);d=r.json();rec('R3-LARGE-WORKSPACE','Upload bounded >5MiB malformed CycloneDX; read quarantine','422 then200; large-file mode and full editor disabled',{'uploadBytes':len(raw),'originalSha256':digest,'session_id':sid,'status':r.status_code,'is_large_file':d.get('is_large_file'),'full_editor_allowed':d.get('full_editor_allowed'),'storage_backend':d.get('storage_backend'),'inline_truncated':d.get('content_inline_truncated')},r.status_code==200 and d['is_large_file'] and not d['full_editor_allowed'])
r=m.call(base+'/content/chunk?source=original&offset=0&limit=4096');c=r.json();r2=m.call(base+'/content-lines?source=original&start_line=1&line_count=15');r3=m.call(base+'/search?source=original&q=r3-large-219&limit=3');rec('R3-LARGE-PAGED-READ','Read bounded chunk, first15 lines, search last component','200 bounded output/total and search result',{'chunkStatus':r.status_code,'chunkBytes':len(c.get('content','')),'total':c.get('total_size'),'eof':c.get('eof'),'linesStatus':r2.status_code,'lineCount':len(r2.json().get('lines',[])),'search':m.payload(r3)},r.status_code==200 and len(c['content'])<=4096 and not c['eof'] and r2.status_code==200 and len(r2.json()['lines'])==15 and r3.status_code==200 and 'r3-large-219' in r3.text)
r=m.call(base+'/repair/analyze','POST');rec('R3-LARGE-ANALYZE','Analyze deterministic semantic error','200 with auto fix',r,r.status_code==200 and r.json().get('auto_fixable',0)>=1)
r=m.call(base+'/repair','POST');rec('R3-LARGE-REPAIR','Generate bounded repair candidate','200 REPAIRED',r,r.status_code==200 and r.json().get('status')=='REPAIRED');assert r.status_code==200 and r.json().get('status')=='REPAIRED';jid=r.json()['repair_job_id'];candidate=m.call(base+'/repair/'+jid+'/download');candidatehash=hashlib.sha256(candidate.content).hexdigest();assert candidate.status_code==200
for role,expected in [('viewer',403),('foreign',404)]:
 r=m.call(base+'/repair/'+jid+'/approve','POST',{'candidate_sha256':candidatehash},role=role);rec('R3-LARGE-DENIAL-'+role,'Attempt candidate approval as '+role,str(expected),r,r.status_code==expected)
r=m.call(base+'/repair/'+jid+'/approve','POST',{'candidate_sha256':candidatehash});rec('R3-LARGE-APPROVE','Explicit Admin approval of reviewed large candidate','200 repaired public UUID',r,r.status_code==200 and bool(r.json().get('imported_sbom_id')));assert r.status_code==200
r=m.call(base+'/download-original');rec('R3-LARGE-ORIGINAL','Download original after import','Original exact bytes preserved',{'status':r.status_code,'bytes':len(r.content),'sha256':hashlib.sha256(r.content).hexdigest()},r.status_code==200 and r.content==raw)
(m.OUT/'large-repair-fixture.json').write_text(json.dumps({'session_id':sid,'job_id':jid,'sourceBytes':len(raw),'sourceSha256':digest,'candidateSha256':candidatehash,'components':220,'owned':'Round3 bounded large fixture'},indent=2))
